using System;using System.Collections.Generic;
namespace UnityEngine{public class Material{public string Name;public Material(string n){Name=n;}}}
public class UIWidget{public string Name;public UnityEngine.Material Value;public int Reads;public UnityEngine.Material material{get{Reads++;return Value;}}}
public class InputManager{static readonly Dictionary<string,string> guiToKeyNameMapping=new Dictionary<string,string>();public static void Types(){string x;guiToKeyNameMapping.TryGetValue("x",out x);guiToKeyNameMapping.Add("x","y");}}
public class UIPanel{public UIWidget[] Widgets;public UnityEngine.Material[] Materials;public List<string> Drawn=new List<string>();void Fill(UnityEngine.Material mat){foreach(var w in Widgets)if(w!=null&&w.material==mat)Drawn.Add(w.Name+":"+(mat==null?"null":mat.Name));}public void LateUpdate(){foreach(var mat in Materials)Fill(mat);}}
class Test{static void Need(bool b,string s){if(!b)throw new Exception(s);}static void Main(){var a=new UnityEngine.Material("A");var b=new UnityEngine.Material("B");var x=new UIWidget{Name="same",Value=a};var y=new UIWidget{Name="same",Value=b};var z=new UIWidget{Name="null-material",Value=null};var p=new UIPanel{Widgets=new[]{x,y,x,z,null},Materials=new[]{a,b}};p.LateUpdate();Need(String.Join(",",p.Drawn.ToArray())=="same:A,same:A,same:B","geometry order/duplicates changed");Need(x.Reads==1&&y.Reads==1&&z.Reads==1,"one getter per identity per call");x.Value=b;p.Drawn.Clear();p.LateUpdate();Need(String.Join(",",p.Drawn.ToArray())=="same:B,same:B,same:B","stale material across updates");Need(x.Reads==2&&y.Reads==2,"call-local lifetime");var other=new UIPanel{Widgets=new[]{x},Materials=new[]{b}};other.LateUpdate();Need(x.Reads==3,"panel isolation");Console.WriteLine("PASS: per-call lifetime, material changes between updates, panel isolation, duplicate identity/names, null widget/material, geometry order");}}
